SELECT Имена_станций.NAME AS name1, w.numb1120, w.numb1, 0 as v,w.YEAR, 1 as var, Имена_областей.NAME AS oblname, Имена_ОЭС.name AS oesname, w.OBL, w.OES ,iif(w.year<=2000,w.kuzn/kn(n.kuzn,0.777,w.year),z(d.[kuznt]/0.81)+z(d.[kuzngd]/0.718)+z(d.[kuznss]/0.803)+z(d.[kuznun]/0.769)) as f01,z(d.nazar/kn(n.nazar,0.484,w.year))+z(d.ibor/kn(n.ibor,0.537,w.year))+z(d.berez/kn(n.berez,0.519,w.year))+z(d.per/kn(n.per,0.537,w.year)) as f02,d.ibor/kn(n.ibor,0.537,w.year) as f03,w.hak/kn(n.hak,0.656,w.year) as f04,z(d.azey/kn(n.azey,0.554,w.year))+z(d.cher/kn(n.cher,0.613,w.year)) as f05,d.azey/kn(n.azey,0.554,w.year) as f06,d.cher/kn(n.cher,0.613,w.year) as f07,z(d.gusin/kn(n.gusin,0.528,w.year))+z(d.tugn/kn(n.tugn,0.708,w.year)) as f08,d.tugn/kn(n.tugn,0.708,w.year) as f09,w.chit/kn(n.chit,0.434,w.year) as f10,w.ner/kn(n.her,0.876,w.year) as f11,w.raich/kn(n.raich,0.38,w.year) as f12,w.prim/kn(n.prim,0.388,w.year) as f13,w.luch/kn(n.luch,0.256,w.year) as f14,w.urg/kn(n.urg,0.645,w.year) as f15 FROM (((([Станции1135_новый] as w left join [доп_угли_1135_новый] as d on w.numb1120=d.numb1120 and w.year=d.year ) inner join имена_станций on w.numb1120=имена_станций.numb ) left join Натура99 as n on w.numb1120=n.numb1120  and w.year=n.year)INNER JOIN Имена_областей ON w.OBL = Имена_областей.OBL) INNER JOIN Имена_ОЭС ON w.OES = Имена_ОЭС.oes Where ((ugol>0) AND (w.er=12)) UNION Select "Всего" as name1,0 as numb1,0 as numb1120,0 as v,w.year,1 as var,null as oblname,null as oesname,0 as oes,0 as obl,sum(iif(w.year<=2000,w.kuzn/kn(n.kuzn,0.777,w.year),z(d.[kuznt]/0.81)+z(d.[kuzngd]/0.718)+z(d.[kuznss]/0.803)+z(d.[kuznun]/0.769))) as f01,sum(z(d.nazar/kn(n.nazar,0.484,w.year))+z(d.ibor/kn(n.ibor,0.537,w.year))+z(d.berez/kn(n.berez,0.519,w.year))+z(d.per/kn(n.per,0.537,w.year))) as f02,sum(d.ibor/kn(n.ibor,0.537,w.year)) as f03,sum(w.hak/kn(n.hak,0.656,w.year)) as f04,sum(z(d.azey/kn(n.azey,0.554,w.year))+z(d.cher/kn(n.cher,0.613,w.year))) as f05,sum(d.azey/kn(n.azey,0.554,w.year)) as f06,sum(d.cher/kn(n.cher,0.613,w.year)) as f07,sum(z(d.gusin/kn(n.gusin,0.528,w.year))+z(d.tugn/kn(n.tugn,0.708,w.year))) as f08,sum(d.tugn/kn(n.tugn,0.708,w.year)) as f09,sum(w.chit/kn(n.chit,0.434,w.year)) as f10,sum(w.ner/kn(n.her,0.876,w.year)) as f11,sum(w.raich/kn(n.raich,0.38,w.year)) as f12,sum(w.prim/kn(n.prim,0.388,w.year)) as f13,sum(w.luch/kn(n.luch,0.256,w.year)) as f14,sum(w.urg/kn(n.urg,0.645,w.year)) as f15 from (([Станции1135_новый] as w left join [доп_угли_1135_новый] as d on w.numb1120=d.numb1120 and w.year=d.year ) inner join имена_станций on w.numb1120=имена_станций.numb ) left join Натура99 as n on w.numb1120=n.numb1120  and w.year=n.year Where ((ugol>0) AND (w.er=12)) and w.ved>0 group by w.year;
